steps.solution:
#include <iostream>
using namespace std;

int main() {
    char command = 'S';

    switch (command) {
        case 'S':
            cout << "SURVEY: ACTIVE" << endl;
            break;
        case 'L':
            cout << "LIDAR: ACTIVE" << endl;
            break;
        default:
            cout << "COMMAND: UNKNOWN" << endl;
            break;
    }

    return 0;
}

