steps.solution:
#include <iostream>
#include <string>
using namespace std;

int main() {
    char tool;
    int battery;
    cin >> tool >> battery;

    string power = (battery >= 40) ? "FULL" : "ECO";

    switch (tool) {
        case 'L':
            cout << "TOOL: LIDAR | POWER: " << power << endl;
            break;
        case 'C':
            cout << "TOOL: CAMERA | POWER: " << power << endl;
            break;
        default:
            cout << "TOOL: STANDBY" << endl;
            break;
    }

    return 0;
}
